// Correct existing stress variance through a generator potential; retain floor f.
#include "m2_rich_protected_variance.cpp"
static double stress_bound(double a,double b,double lam){return a*((4*lam+2)/std::exp(1.)+b*(1+2*lam)/std::sqrt(2*lam*std::exp(1.))+2*lam);}
static void available_time(double t,double k,double D,const double*ends,double&q,double&qd){const double pi=std::acos(-1.);double a,ap,A;if(t<ends[0]){A=pi/(2*ends[0]);a=std::pow(std::cos(A*t),2);ap=-A*std::sin(2*A*t);}else if(t>=ends[15]){double tau=10./365;A=pi/(2*tau);double x=t-ends[15];a=x>=tau?1:std::pow(std::sin(A*x),2);ap=x>=tau?0:A*std::sin(2*A*x);}else{int j=0;while(t>=ends[j+1])++j;A=pi/(ends[j+1]-ends[j]);double v=A*(t-ends[j]);a=std::pow(std::sin(v),2);ap=A*std::sin(2*v);}double B=2*k*std::sqrt(2/(pi*std::exp(1.)))+D,K=B/2+std::sqrt(A*A+B*B/4);q=a/K;qd=ap/K;}
extern "C" void available_probe(int n,const double*t,const double*u,const double*z,const double*rate,const double*cfg,const double*ends,double*out){double k=cfg[0],a=cfg[1],b=cfg[2],lam=cfg[3];for(int i=0;i<n;++i){double q,qd;available_time(t[i],k,stress_bound(a,b,lam),ends,q,qd);double v=-std::expm1(-2*a*t[i]),y=z[i]-b*v,g=std::exp(-lam*y*y),A=std::exp(b*z[i]-.5*b*b*v),phi=std::erf(u[i]/std::sqrt(2.)),lp=-2*k*u[i]*std::sqrt(2/std::acos(-1.))*std::exp(-u[i]*u[i]/2),D=a*((4*lam*lam+2*lam)*y*y-b*(1+2*lam*v)*y-2*lam);out[3*i]=q*phi*A*g;out[3*i+1]=A*g*(qd*phi+q*lp+q*phi*D);out[3*i+2]=A;}}
extern "C" void available_stock(int nt,int pairs,int nd,int ne,int na,const int*tr,const double*dec,const double*root,const double*cross,const double*mean,const double*proj,const double*time,const double*dt,const int*seg,const int*coarse,const int*reference,const int*expiry,const double*norm,const double*p,const double*models,const double*alpha,const double*normalizers,double scale,uint64_t seed,double*out){
 Model m(models);const double*ends=normalizers+3;std::vector<double>qa(nt*12),qd(nt*12),rq(nt),rd(nt);double ar[2]={m.as,m.af},br[2]={m.bs,m.bf};for(int t=0;t<nt;++t){rich_time(time[t],normalizers[1],1,1,rq[t],rd[t]);for(int j=0;j<6;++j)for(int c=0;c<2;++c){double lam=j%2?.5:.125;available_time(time[t],normalizers[j/2],stress_bound(ar[c],br[c],lam),ends,qa[t*12+2*j+c],qd[t*12+2*j+c]);}}std::vector<double>ds(nt),df(nt),ns(nt),nf(nt),cs(nt),cf(nt),rs(nt),rf(nt),qs(nt),qf(nt);for(int t=0;t<nt;++t){double h=dt[t];ds[t]=std::exp(-m.as*h);df[t]=std::exp(-m.af*h);ns[t]=std::sqrt(-std::expm1(-2*m.as*h));nf[t]=std::sqrt(-std::expm1(-2*m.af*h));rs[t]=std::sqrt(residual(m.as,h));rf[t]=std::sqrt(residual(m.af,h));cs[t]=std::sqrt(h-rs[t]*rs[t]);cf[t]=std::sqrt(h-rf[t]*rf[t]);qs[t]=-std::expm1(-2*m.as*time[t]);qf[t]=-std::expm1(-2*m.af*time[t]);}
 auto worker=[&](int begin,int end){for(int i=begin;i<end;++i){std::vector<double>s(nd,0),next(nd),z(nd+1),logs(4*na,0),hold(2*na,0);double zs=0,zf=0,refv[2]={},reflog[2]={};
 for(int t=0;t<nt;++t){uint64_t k=(uint64_t(t)*pairs+i)*(nd+3);for(int j=0;j<nd+1;++j)z[j]=gaussian(seed,k+j);double dw=std::sqrt(dt[t])*z[0],es=gaussian(seed,k+nd+1),ef=gaussian(seed,k+nd+2),bs=cs[t]*es+rs[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*(uint64_t(t)*pairs+i)),bf=cf[t]*ef+rf[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*(uint64_t(t)*pairs+i)+1),shock=.6*dw-.8*(std::sqrt(1-m.r)*bs+std::sqrt(m.r)*bf),pr[3]={};for(int j=0;j<nd;++j)for(int c=0;c<3;++c)pr[c]+=proj[c*nd+j]*s[j];
 for(int anti=0;anti<2;++anti){double sign=anti?-1:1,C=mean[3*t]+sign*pr[0],Y=mean[3*t+1]+sign*pr[1],F=mean[3*t+2]+sign*pr[2],old=G(p[0]*C+p[1]*std::pow(Y-p[2],2)+p[3]*std::pow(F-p[4],2),p)*std::exp(-norm[t]);double stress=(1-m.r)*std::exp(sign*m.bs*zs-.5*m.bs*m.bs*qs[t])+m.r*std::exp(sign*m.bf*zf-.5*m.bf*m.bf*qf[t]),H=(1-m.w)*old+m.w*stress,l=sp(-sign*pr[1]/scale);
 double hh[6];const int indices[3]={7,6,5};double zz[2]={sign*zs,sign*zf},qq[2]={qs[t],qf[t]},aa[2]={std::exp(sign*m.bs*zs-.5*m.bs*m.bs*qs[t]),std::exp(sign*m.bf*zf-.5*m.bf*m.bf*qf[t])};for(int j=0;j<6;++j){double u=sign*s[indices[j/2]],rate=normalizers[j/2],lam=j%2?.5:.125,phi=std::erf(u/std::sqrt(2.)),lp=-2*rate*u*std::sqrt(2/std::acos(-1.))*std::exp(-u*u/2),sum=0;for(int c=0;c<2;++c){double y=zz[c]-br[c]*qq[c],g=std::exp(-lam*y*y),D=ar[c]*((4*lam*lam+2*lam)*y*y-br[c]*(1+2*lam*qq[c])*y-2*lam),q=qa[t*12+2*j+c],dq=qd[t*12+2*j+c];sum+=(c?m.r:1-m.r)*aa[c]*g*(dq*phi+q*lp+q*phi*D);}hh[j]=(.2-m.f)*models[seg[t]]*m.w*sum;}
 double previous=.5*m.f*rich_value(rq[t],rd[t],sign*s[6],normalizers[1],1,1);for(int a=0;a<na;++a){const double*x=models+23*a;const double*cfg=alpha+4*a;double v=m.f+(.2-m.f)*x[seg[t]]*H;if(int(cfg[3])==1)v+=previous;else if(int(cfg[3])==2)v+=cfg[2]*hh[int(cfg[0])*2+int(cfg[1])];if(coarse[t])hold[anti*na+a]=v;for(int grid=0;grid<2;++grid){double vv=grid?v:hold[anti*na+a];logs[(anti*na+a)*2+grid]+=-.5*vv*dt[t]+std::sqrt(vv)*sign*shock;}}
 if(reference[t])refv[anti]=m.f+(.2-m.f)*models[seg[t]]*((1-m.w)+m.w*stress);reflog[anti]+=-.5*refv[anti]*dt[t]+std::sqrt(refv[anti])*sign*shock;
 if(expiry[t]>=0){double*o=out+((uint64_t(anti*pairs+i)*ne+expiry[t])*(na+1)*2);for(int a=0;a<na;++a)for(int grid=0;grid<2;++grid)o[2*a+grid]=std::exp(logs[(anti*na+a)*2+grid]);o[2*na]=o[2*na+1]=std::exp(reflog[anti]);}
 }
 const double*r=root+uint64_t(tr[t])*nd*nd;for(int j=0;j<nd;++j){double v=cross[tr[t]*nd+j]*dw;for(int l=0;l<nd;++l)v+=r[j*nd+l]*z[l+1];next[j]=dec[tr[t]*nd+j]*s[j]+v;}s.swap(next);zs=ds[t]*zs+ns[t]*es;zf=df[t]*zf+nf[t]*ef;
 }}};std::vector<std::thread>threads;for(int j=0;j<4;++j)threads.emplace_back(worker,pairs*j/4,pairs*(j+1)/4);for(auto&t:threads)t.join();
}
